# Generated by ha2pg3 from descriptor 'sonos.json'. Edit the backend, not the glue.
#!/usr/bin/env python3
"""
Sonos plugin for Universal Devices PG3x (eisy / Polisy).

Ported from the Home Assistant "sonos" integration
with the ha2pg3 converter. All device communication lives in backend.py.
"""
import udi_interface
import sys
import re
import json
import backend
from nodes import DeviceNode

LOGGER = udi_interface.LOGGER
Custom = udi_interface.Custom
VERSION = "0.1.0"


class Controller(udi_interface.Node):
    """Controller: owns discovery and polling."""

    id = 'controller'
    def __init__(self, polyglot, primary, address, name):
        super(Controller, self).__init__(polyglot, primary, address, name)
        self.poly = polyglot
        self.name = name
        self.discovery = False
        self.Params = Custom(polyglot, 'customparams')

        self.poly.subscribe(self.poly.POLL, self.poll)
        self.poly.subscribe(self.poly.CUSTOMPARAMS, self.handle_params)
        self.poly.subscribe(self.poly.DISCOVER, self.discover)

        LOGGER.info("Starting Sonos eisy plugin version {}".format(VERSION))

        polyglot.ready()
        polyglot.addNode(self, conn_status="ST")

        self.params = []

    # ------------------------------------------------------------ lifecycle
    def handle_params(self, params):
        LOGGER.debug("Custom params: {}".format(params))
        self.Params.load(params)

        self.params = []
        for param in self.Params:
            match = re.match("sonos_(.*)", param, re.I)
            if match is not None:
                address = match.group(1).lower()
                try:
                    LOGGER.debug('JSON load parameter: {}'.format(param))
                    LOGGER.debug('JSON load : {}'.format(self.Params[param]))
                    speaker_info = json.loads(self.Params[param])
                    LOGGER.debug('At 6')
                    if 'name' in speaker_info and 'host' in speaker_info:
                        LOGGER.debug('At 7')
                        self.params.append({'address':address, 'name': speaker_info['name'], 'ip': speaker_info['host']})
                    else:
                        LOGGER.debug('speaker_info missing data: {}'.format(speaker_info))
                except:
                    err = sys.exc_info()[0]
                    LOGGER.error('Paramenter error {}'.format(err))
            else:
                LOGGER.debug('Config has no manual speakers listed')


        self.discover()

    # ------------------------------------------------------------ discovery
    def discover(self):

        if self.discovery:
            LOGGER.debug("Attempt to run discover while it's already running")
            return
        self.discovery = True

        """Ask the backend for devices; create/bind one node per device."""
        LOGGER.info('Starting Speaker Discovery...')
        self.poly.Notices.clear()

        try:
            devices = backend.discover_devices(self.params)
        except Exception as ex:
            LOGGER.error("Discovery failed: {}".format(ex), exc_info=True)
            return

        LOGGER.info("Discovered {} device(s)".format(len(devices)))
        for info in devices:
            node = self.poly.getNode(info["address"])
            if node is None:
                LOGGER.info("Adding speaker {} {}".format(info["name"], info["address"]))
                node = DeviceNode(
                    self.poly, self.address, info["address"], info["name"]
                )
                self.poly.addNode(node)
            node.bind(info["device"])
            node.update()

        self.discovery = False

    def cmd_discover(self, command):
        self.discover()

    # ------------------------------------------------------------ polling
    def poll(self, polltype):
        if polltype == "longPoll":
            self.discover()  # pick up devices added/removed since last poll
        else:
            for node in self.poly.nodes():
                if node.address != self.address and hasattr(node, "update"):
                    node.update()
    drivers = [
            {'driver': 'ST', 'value': 1, 'uom': '25', 'name': 'Status'}
            ]
    commands = {'DISCOVER': cmd_discover}

if __name__ == "__main__":
    try:
        polyglot = udi_interface.Interface([])

        polyglot.start(VERSION)
        polyglot.setCustomParamsDoc()
        polyglot.updateProfile()
        control = Controller(polyglot, "sonosctrl", "sonosctrl", "Sonos Controller")

        polyglot.runForever()
    except (KeyboardInterrupt, SystemExit):
        sys.exit(0)
    except Exception as err:
        LOGGER.error("Exception: {}".format(err), exc_info=True)
        sys.exit(1)
